.dashboard {
  display: grid;
  gap: 1rem;
}

.metric-list {
  container-type: inline-size;
}

@media (min-width: 48rem) {
  .dashboard {
    grid-template-columns: 14rem minmax(0, 1fr);
  }
}

@container (min-width: 34rem) {
  .metric-list {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1rem;
  }
}
